export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

/** Per-category rate and validation limits. */
const CATEGORY = {
  standard: { basePerNight: 80, highPerNight: 30, maxNights: 14, maxGuests: 2 },
  suite: { basePerNight: 150, highPerNight: 60, maxNights: 21, maxGuests: 4 },
  villa: { basePerNight: 300, highPerNight: 120, maxNights: 28, maxGuests: 8 },
} as const;

type CategoryName = keyof typeof CATEGORY;

function isSeasonable(value: unknown): value is "low" | "high" {
  return value === "low" || value === "high";
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;
  if (!Number.isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) {
    return { ok: false, error: "bad loyalty" };
  }

  const name = req.category as CategoryName;
  const conf = CATEGORY[name];
  if (!conf) {
    return { ok: false, error: "unknown category" };
  }

  const nights = req.nights as number;
  if (!Number.isInteger(nights) || nights < 1 || nights > conf.maxNights) {
    return { ok: false, error: "bad nights" };
  }
  if (name === "villa" && nights < 3) {
    return { ok: false, error: "villa minimum stay" };
  }

  const guests = req.guests as number;
  if (!Number.isInteger(guests) || guests < 1 || guests > conf.maxGuests) {
    return { ok: false, error: "bad guests" };
  }

  if (!isSeasonable(req.season)) {
    return { ok: false, error: "bad season" };
  }

  // Discount and refund-policy tiers are identical across every category:
  // a guest qualifies when they hold a VIP coupon or have 3+ years of loyalty.
  const privileged = req.coupon === "VIP" || (req.loyaltyYears as number) >= 3;

  let total = conf.basePerNight * nights;
  if (req.season === "high") {
    total += conf.highPerNight * nights;
  }
  if (privileged) {
    total -= Math.floor(total / 10);
  }

  // Category-specific extras.
  if (name === "suite" && guests > 2) {
    total += 25;
  }
  if (name === "villa") {
    total += 500;
  }

  const policy = privileged ? "flex" : "strict";
  const line = `${name}:${nights}n:${total}:${policy}`;
  return { ok: true, total, policy, line };
}

